namespace UniversalPOS.Domain.Entities;
public class UserPermissionOverride { public int Id {get; private set;} public int UserId {get; private set;} public User? User {get; private set;} public int PermissionId {get; private set;} public Permission? Permission {get; private set;} public bool IsGranted {get; private set;} public string Reason {get; private set;}=string.Empty; public int? ChangedByUserId {get; private set;} public DateTime ChangedAtUtc {get; private set;}=DateTime.UtcNow; private UserPermissionOverride(){} public UserPermissionOverride(int userId,int permissionId,bool isGranted,string reason,int? changedByUserId){if(userId<=0||permissionId<=0)throw new ArgumentOutOfRangeException("IDs must be positive.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("A reason is required for permission overrides.");UserId=userId;PermissionId=permissionId;IsGranted=isGranted;Reason=reason.Trim();ChangedByUserId=changedByUserId;} }
